#include <iostream>
using namespace std;

int cifraControl(int n)
{
    int s;
    while (n > 9)
    {
        s = 0;
        while (n != 0)
        {
            s = s + n % 10;
            n = n / 10;
        }
        n = s;
    }
    return n;
}

int main()
{
    int n;
    cin >> n;
    cout << cifraControl(n);
    return 0;
}

#include <iostream>
using namespace std;

bool estePrim(int n)
{
    if (n < 2) return false;
    for (int d = 2; d * d <= n; d++)
        if (n % d == 0) return false;
    return true;
}

void afisareNumerePrime(int a, int b)
{
    for (int i = a; i <= b; i++)
        if (estePrim(i)) cout << i << " ";
}

int main()
{
    int a, b;
    cin >> a >> b;
    afisareNumerePrime(a, b);
    return 0;
}

