#include <iostream>
using namespace std;
struct Account { char owner[50]; double balance; };
void transfer(Account &from, Account &to, double amount) {
    if (from.balance >= amount) { from.balance -= amount; to.balance += amount; }
}
int main() {
    Account a1, a2; double amt; cin >> a1.owner >> a1.balance >> a2.owner >> a2.balance >> amt;
    transfer(a1, a2, amt); cout << a1.balance << endl << a2.balance;
    return 0;
}

