#include <algorithm>
using namespace std;
int main() {
    int n, m; double med[30]; cin >> n >> m;
    for (int i = 0; i < n; i++) {
        int s = 0, x; for (int j = 0; j < m; j++) { cin >> x; s += x; }
        med[i] = (double)s / m;
    }
    sort(med, med + n, greater<double>());
    for (int i = 0; i < n; i++) cout << fixed << setprecision(2) << med[i] << " ";
    return 0;
}

#include <iostream>
using namespace std;
int main() {
    int L, Z, zid, M, P, T, t[10005] = {0}; bool z[10005] = {0};
    cin >> L >> Z; for (int i = 0; i < Z; i++) { cin >> zid; z[zid] = 1; }
    cin >> M; for (int i = 0; i < M; i++) {
        cin >> P >> T; if (z[T]) continue;
        for (int d = 0; d < P; d++) {
            if (T - d >= 1 && !z[T - d]) t[T - d] += (P - d); else break;
        }
        for (int d = 1; d < P; d++) {
            if (T + d <= L && !z[T + d]) t[T + d] += (P - d); else break;
        }
    }
    for (int i = 1; i <= L; i++) cout << (z[i] ? -1 : t[i]) << " ";
    return 0;
}
